public struct AllTypesSubMsg: OmniBufMessage, Equatable, Sendable {
    public var id: UInt32
    public var label: String
    public var flag: Bool
    public var score: Int64

    public init(
        id: UInt32 = 0,
        label: String = "",
        flag: Bool = false,
        score: Int64 = 0
    ) {
        self.id = id
        self.label = label
        self.flag = flag
        self.score = score
    }

    public init() {
        self.init(id: 0)
    }

    @inlinable
    public var estimatedOmniBufSize: Int {
        var n = 16
        n &+= label.utf8.count
        return n
    }

    @inlinable
    public func marshalOmniBuf() -> [UInt8] {
        var w = OmniBufWriter(initialCapacity: max(256, estimatedOmniBufSize))
        encodeOmniBufBodyFast(into: &w, deterministic: true)
        return w.toBytes()
    }

    @inlinable
    public func encodeOmniBufBody(into writer: inout OmniBufWriter, options: EncodeOptions) throws {
        encodeOmniBufBodyFast(into: &writer, deterministic: options.deterministic)
    }

    @inlinable
    public func encodeOmniBufBodyFast(into w: inout OmniBufWriter, deterministic: Bool) {
        if self.id != 0 {
            w.appendTag(fieldNumber: 1, wireType: WireType.wireUint)
            w.appendVarint(UInt64(self.id))
        }
        if !self.label.isEmpty {
            w.appendTag(fieldNumber: 2, wireType: WireType.wireString)
            w.appendStringValue(self.label)
        }
        if self.flag {
            w.appendTag(fieldNumber: 3, wireType: WireType.wireBoolTrue)
        }
        if self.score != 0 {
            w.appendTag(fieldNumber: 4, wireType: WireType.wireSint)
            w.appendZigZag(self.score)
        }
    }

    @inlinable
    public mutating func mergeOmniBuf(from data: UnsafeBufferPointer<UInt8>, depth: Int, budget: inout DecodeBudget) throws {
        guard depth <= budget.maxDepth else {
            throw OmniBufError.depthLimitExceeded(depth)
        }
        var r = OmniBufReader(data)
        while !r.isAtEnd {
            let (fnum, wt) = try r.readTag()
            switch fnum {
            case 0:
                guard wt == WireType.wireSubMsg else {
                    throw OmniBufError.parse("Field #0 must have WireSubMsg (12), got \(wt)")
                }
                let slice = try r.readLenSlice()
                _ = try SchemaMeta.validateSlice(slice, depth: depth &+ 1, maxDepth: budget.maxDepth)
            case 1:
                guard wt == WireType.wireUint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = UInt32(truncatingIfNeeded: try r.readVarint())
                self.id = val
            case 2:
                guard wt == WireType.wireString else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readString()
                try budget.addAlloc(val.utf8.count)
                self.label = val
            case 3:
                if wt == WireType.wireBoolFalse {
                    self.flag = false
                } else if wt == WireType.wireBoolTrue {
                    self.flag = true
                } else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                }
            case 4:
                guard wt == WireType.wireSint else {
                    try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
                    continue
                }
                let val = try r.readSint64()
                self.score = val
            default:
                try r.validateValue(wireType: wt, inCollection: false, depth: depth, maxDepth: budget.maxDepth)
            }
        }
    }

    public static var omniBufSchemaMeta: SchemaMeta {
        var fields: [UInt32: String] = [:]
        let children: [UInt32: SchemaMeta] = [:]
        fields[1] = "id"
        fields[2] = "label"
        fields[3] = "flag"
        fields[4] = "score"
        return SchemaMeta(typeName: "AllTypesSubMsg", fields: fields, children: children)
    }
}

public struct OpaqueAllTypesSubMsg: Sendable {
    public let raw: [UInt8]
    public let offset: Int
    public let length: Int
    @usableFromInline internal var dirtyMask: UInt64 = 0
    @usableFromInline internal var dirty_id: UInt32 = 0
    @usableFromInline internal var dirty_label: String = ""
    @usableFromInline internal var dirty_flag: Bool = false
    @usableFromInline internal var dirty_score: Int64 = 0

    @inlinable
    public init(_ raw: [UInt8]) {
        self.raw = raw
        self.offset = 0
        self.length = raw.count
    }

    @inlinable
    public init(raw: [UInt8], offset: Int, length: Int) {
        self.raw = raw
        self.offset = offset
        self.length = length
    }

    @inlinable
    @inline(__always)
    internal func withSlice<R>(_ body: (UnsafeBufferPointer<UInt8>) -> R) -> R {
        raw.withUnsafeBufferPointer { buf in
            body(UnsafeBufferPointer(start: buf.baseAddress?.advanced(by: offset), count: length))
        }
    }

    @inlinable
    public func getId() -> UInt32 {
        if (dirtyMask & (1 &<< 1)) != 0 { return dirty_id }
        return withSlice { OpaqueWire.readUint32(in: $0, fieldNumber: 1) }
    }
    @inlinable
    public mutating func setId(_ value: UInt32) {
        dirty_id = value
        dirtyMask |= (1 &<< 1)
    }
    @inlinable
    public func getLabel() -> String {
        if (dirtyMask & (1 &<< 2)) != 0 { return dirty_label }
        return withSlice { OpaqueWire.readString(in: $0, fieldNumber: 2) }
    }
    @inlinable
    public mutating func setLabel(_ value: String) {
        dirty_label = value
        dirtyMask |= (1 &<< 2)
    }
    @inlinable
    public func getFlag() -> Bool {
        if (dirtyMask & (1 &<< 3)) != 0 { return dirty_flag }
        return withSlice { OpaqueWire.readBool(in: $0, fieldNumber: 3) }
    }
    @inlinable
    public mutating func setFlag(_ value: Bool) {
        dirty_flag = value
        dirtyMask |= (1 &<< 3)
    }
    @inlinable
    public func getScore() -> Int64 {
        if (dirtyMask & (1 &<< 4)) != 0 { return dirty_score }
        return withSlice { OpaqueWire.readSint64(in: $0, fieldNumber: 4) }
    }
    @inlinable
    public mutating func setScore(_ value: Int64) {
        dirty_score = value
        dirtyMask |= (1 &<< 4)
    }

    @inlinable
    internal func appendDirtyField(_ fnum: UInt16, into w: inout OmniBufWriter) {
        let deterministic = true
        _ = deterministic
        switch fnum {
        case 1:
            if self.dirty_id != 0 {
                w.appendTag(fieldNumber: 1, wireType: WireType.wireUint)
                w.appendVarint(UInt64(self.dirty_id))
            }
        case 2:
            if !self.dirty_label.isEmpty {
                w.appendTag(fieldNumber: 2, wireType: WireType.wireString)
                w.appendStringValue(self.dirty_label)
            }
        case 3:
            if self.dirty_flag {
                w.appendTag(fieldNumber: 3, wireType: WireType.wireBoolTrue)
            }
        case 4:
            if self.dirty_score != 0 {
                w.appendTag(fieldNumber: 4, wireType: WireType.wireSint)
                w.appendZigZag(self.dirty_score)
            }
        default:
            break
        }
    }

    @inlinable
    public func marshal() -> [UInt8] {
        if dirtyMask == 0 { return raw }
        var dst: [UInt8] = []
        OpaqueWire.spliceFields(into: &dst, raw: raw, dirtyMask: dirtyMask, maxField: 4) { w, fnum in
            self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }

    @inlinable
    public func tryMarshal() throws -> [UInt8] {
        var dst: [UInt8] = []
        try OpaqueWire.trySpliceFields(into: &dst, raw: raw, dirtyMask: dirtyMask, maxField: 4) { w, fnum in
            self.appendDirtyField(fnum, into: &w)
        }
        return dst
    }
}

public struct TestAllTypes: OmniBufMessage, Equatable, Sendable {
