        f14Float64: Double = 0,
        f15Fixed32: UInt32 = 0,
        f16Fixed64: UInt64 = 0,
        f20OverflowStr: String = ""
    ) {
        self.f1Uint32 = f1Uint32
        self.f2Uint64 = f2Uint64
        self.f3Sint32 = f3Sint32
        self.f4Sint64 = f4Sint64
        self.f5Bool = f5Bool
        self.f6String = f6String
        self.f7Bytes = f7Bytes
        self.f8SubMsg = f8SubMsg
        self.f9StringArr = f9StringArr
        self.f10Uint32Arr = f10Uint32Arr
        self.f11SubMsgArr = f11SubMsgArr
        self.f12MapStrUint = f12MapStrUint
        self.f13Float32 = f13Float32
        self.f14Float64 = f14Float64
        self.f15Fixed32 = f15Fixed32
        self.f16Fixed64 = f16Fixed64
        self.f20OverflowStr = f20OverflowStr
