        self.init(f1Uint32: 0)
    }

    @inlinable
    public var estimatedOmniBufSize: Int {
        var n = 68
        n &+= f6String.utf8.count
        n &+= f7Bytes.count
        if let m = f8SubMsg { n &+= m.estimatedOmniBufSize &+ 4 }
        for s in f9StringArr { n &+= s.utf8.count &+ 4 }
        n &+= f10Uint32Arr.count &* 8
        for m in f11SubMsgArr { n &+= m.estimatedOmniBufSize &+ 4 }
        n &+= f12MapStrUint.count &* 24
        n &+= f20OverflowStr.utf8.count
        return n
    }

    @inlinable
    public func marshalOmniBuf() -> [UInt8] {
        var w = OmniBufWriter(initialCapacity: max(256, estimatedOmniBufSize))
