        if self.f1Uint32 != 0 {
            w.appendTag(fieldNumber: 1, wireType: WireType.wireUint)
            w.appendVarint(UInt64(self.f1Uint32))
        }
        if self.f2Uint64 != 0 {
            w.appendTag(fieldNumber: 2, wireType: WireType.wireUint)
            w.appendVarint(self.f2Uint64)
        }
        if self.f3Sint32 != 0 {
            w.appendTag(fieldNumber: 3, wireType: WireType.wireSint)
            w.appendZigZag32(self.f3Sint32)
        }
        if self.f4Sint64 != 0 {
            w.appendTag(fieldNumber: 4, wireType: WireType.wireSint)
            w.appendZigZag(self.f4Sint64)
        }
        if self.f5Bool {
            w.appendTag(fieldNumber: 5, wireType: WireType.wireBoolTrue)
        }
        if !self.f6String.isEmpty {
            w.appendTag(fieldNumber: 6, wireType: WireType.wireString)
            w.appendStringValue(self.f6String)
        }
        if !self.f7Bytes.isEmpty {
            w.appendTag(fieldNumber: 7, wireType: WireType.wireBytes)
            w.appendBytes(self.f7Bytes)
        }
        if let sub = self.f8SubMsg {
            w.appendTag(fieldNumber: 8, wireType: WireType.wireSubMsg)
            if sub.estimatedOmniBufSize > 16_383 {
                let lenPos = w.reserveLength4()
                sub.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                w.backpatchLength4(at: lenPos)
            } else {
                let lenPos = w.reserveLength2()
                sub.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                w.backpatchLength2(at: lenPos)
            }
        }
        if !self.f9StringArr.isEmpty {
            w.appendTag(fieldNumber: 9, wireType: WireType.wireArray)
            let lenPos = w.reserveLength2()
            w.appendByte(WireType.wireString)
            w.appendVarint(UInt64(self.f9StringArr.count))
            for elem in self.f9StringArr {
                w.appendStringValue(elem)
            }
            w.backpatchLength2(at: lenPos)
        }
        if !self.f10Uint32Arr.isEmpty {
            w.appendTag(fieldNumber: 10, wireType: WireType.wireArray)
            let lenPos = w.reserveLength2()
            w.appendByte(WireType.wireUint)
            w.appendVarint(UInt64(self.f10Uint32Arr.count))
            for elem in self.f10Uint32Arr {
                w.appendVarint(UInt64(elem))
            }
            w.backpatchLength2(at: lenPos)
        }
        if !self.f11SubMsgArr.isEmpty {
            w.appendTag(fieldNumber: 11, wireType: WireType.wireArray)
            var arrEst = 8
            for elem in self.f11SubMsgArr { arrEst &+= elem.estimatedOmniBufSize &+ 4 }
            if arrEst > 16_383 {
                let lenPos = w.reserveLength4()
                w.appendByte(WireType.wireSubMsg)
                w.appendVarint(UInt64(self.f11SubMsgArr.count))
