                    if elem.estimatedOmniBufSize > 16_383 {
                        let elemLenPos = w.reserveLength4()
                        elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                        w.backpatchLength4(at: elemLenPos)
                    } else {
                        let elemLenPos = w.reserveLength2()
                        elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                        w.backpatchLength2(at: elemLenPos)
                    }
                }
                w.backpatchLength4(at: lenPos)
            } else {
                let lenPos = w.reserveLength2()
                w.appendByte(WireType.wireSubMsg)
                w.appendVarint(UInt64(self.f11SubMsgArr.count))
                for elem in self.f11SubMsgArr {
                    let elemLenPos = w.reserveLength2()
                    elem.encodeOmniBufBodyFast(into: &w, deterministic: deterministic)
                    w.backpatchLength2(at: elemLenPos)
                }
                w.backpatchLength2(at: lenPos)
            }
        }
        if !self.f12MapStrUint.isEmpty {
            w.appendTag(fieldNumber: 12, wireType: WireType.wireMap)
            let lenPos = w.reserveLength2()
            w.appendTwoBytes(WireType.wireString, WireType.wireUint)
            w.appendVarint(UInt64(self.f12MapStrUint.count))
            if deterministic {
                for k in self.f12MapStrUint.keys.sorted(by: compareUTF8Bytes) {
                    w.appendStringValue(k)
                    w.appendVarint(self.f12MapStrUint[k]!)
                }
            } else {
                for (k, v) in self.f12MapStrUint {
                    w.appendStringValue(k)
                    w.appendVarint(v)
                }
            }
            w.backpatchLength2(at: lenPos)
        }
        if self.f13Float32.bitPattern != 0 {
            w.appendTag(fieldNumber: 13, wireType: WireType.wireFloat32)
            w.appendFloat32(self.f13Float32)
        }
        if self.f14Float64.bitPattern != 0 {
            w.appendTag(fieldNumber: 14, wireType: WireType.wireFloat64)
            w.appendFloat64(self.f14Float64)
        }
        if self.f15Fixed32 != 0 {
            w.appendTag(fieldNumber: 15, wireType: WireType.wireFixed32)
            w.appendFixed32(self.f15Fixed32)
        }
        if self.f16Fixed64 != 0 {
            w.appendTag(fieldNumber: 16, wireType: WireType.wireFixed64)
            w.appendFixed64(self.f16Fixed64)
        }
        if !self.f20OverflowStr.isEmpty {
            w.appendTag(fieldNumber: 20, wireType: WireType.wireString)
            w.appendStringValue(self.f20OverflowStr)
        }
    }

